const {chromium}=require('playwright');const fs=require('fs');const assert=require('node:assert/strict');
(async()=>{const browser=await chromium.launch({headless:false});const page=await browser.newPage();try{await page.route('http://studio-fixture.test/**',async route=>{if(route.request().url().endsWith('/providers')){await new Promise(r=>setTimeout(r,25));return route.fulfill({json:{configured:['dashscope']}})}return route.fulfill({contentType:'text/html',body:'<div id="root"></div><script>'+fs.readFileSync('/tmp/studio-request-fixture.js','utf8')+'</script>'})});await page.goto('http://studio-fixture.test/');await page.waitForFunction(()=>window.providerCalls>0);await page.waitForTimeout(1500);const counts=await page.evaluate(()=>({providers:window.providerCalls,polls:window.pollCalls}));console.log(counts);assert.equal(counts.providers,1,'provider configuration must be fetched once per mount');assert.equal(counts.polls,0,'pending approval must not poll job progress');}finally{await browser.close()}})();
